  cursor: pointer !important;
}
.msg-videocall-card:active { transform: scale(0.97); }

.msg-videocall-card::before { display: none !important; }

.msg-videocall-icon {
  width: 26px !important; height: 18px !important; min-width: 26px !important; max-width: 26px !important;
